			 LIBCERROR_ENCRYPTION_ERROR_DECRYPT_FAILED,
			 "%s: unable to decrypt data.",
			 function );

			goto on_error;
		}
		sector_number += 1;
	}
	return( 1 );

on_error:
	memory_set(
	 tweak_value,
	 0,
	 16 );

	return( -1 );
}

